/// True for the interface-wrap error enums `ToStatus()` covers.
template <typename E>
inline constexpr bool kIsIiwError =
    std::is_same_v<E, hf_adc_err_t> ||
    std::is_same_v<E, hf_bluetooth_err_t> ||
    std::is_same_v<E, hf_can_err_t> ||
    std::is_same_v<E, hf_gpio_err_t> ||
    std::is_same_v<E, hf_i2c_err_t> ||
    std::is_same_v<E, hf_logger_err_t> ||
    std::is_same_v<E, hf_nvs_err_t> ||
    std::is_same_v<E, hf_timer_err_t> ||
    std::is_same_v<E, hf_pio_err_t> ||
    std::is_same_v<E, hf_pwm_err_t> ||
    std::is_same_v<E, hf_spi_err_t> ||
    std::is_same_v<E, hf_temp_err_t> ||
    std::is_same_v<E, hf_uart_err_t> ||
    std::is_same_v<E, hf_wifi_err_t>;

/// `Ok()` for a success code, otherwise a failure with `ToStatus(error)` and the native code as detail.
template <typename E>
    requires kIsIiwError<E>
[[nodiscard]] constexpr Result<void> ToResult(E error) noexcept {
    const Status status = ToStatus(error);
    if (status == Status::Ok) {
        return {};
    }
    return Fail(status, static_cast<std::uint32_t>(error));
}

